CREATE COLUMN TABLE "TEST_AP"."OUGR" ("GroupId" SMALLINT CS_INT NOT NULL , "GroupName" NVARCHAR(155) NOT NULL , "GroupDec" NVARCHAR(155), "Allowences" NCLOB MEMORY THRESHOLD 1000, "TPLId" SMALLINT CS_INT, "StartDate" LONGDATE CS_LONGDATE, "DueDate" LONGDATE CS_LONGDATE, "GroupType" NVARCHAR(1) DEFAULT 'A', "CockpitId" SMALLINT CS_INT, PRIMARY KEY ("GroupId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OUGR_NAME_KEY" ON "TEST_AP"."OUGR" ( "GroupName" ASC )